const executeScript = async ({
  name,
  script,
  indexPatternTitle,
  query,
  additionalFields = [],
  http
}) => {
  return http.post('/internal/index-pattern-management/preview_scripted_field', {
    body: JSON.stringify({
      index: indexPatternTitle,
      name,
      script,
      query,
      additionalFields
    })
  }).then(res => ({
    status: res.statusCode,
    hits: res.body.hits
  })).catch(err => ({
    status: err.statusCode,
    error: err.body.attributes.error
  }));
};
const isScriptValid = async ({
  name,
  script,
  indexPatternTitle,
  http
}) => {
  const scriptResponse = await executeScript({
    name,
    script,
    indexPatternTitle,
    http
  });
  if (scriptResponse.status !== 200) {
    return false;
  }
  return true;
};

